import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Qvwhmedc.js";var i=JSON.parse(`{"title":"Performing A Release","description":"","frontmatter":{"title":"Performing A Release"},"headers":[],"relativePath":"guides/contributing/RELEASE.md","filePath":"guides/contributing/RELEASE.md"}`),a={name:`guides/contributing/RELEASE.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to “Release”">​</a></h1><p>The WarpDrive release process is mostly automated but requires manually configuring and triggering the appropriate workflow.</p><p>There are four standard and two non-standard release channels</p><ul><li>standard releases: <code>lts</code>, <code>release</code>, <code>beta</code>, <code>canary</code>.</li><li>non-standard releases: <code>lts-prev</code> <code>release-prev</code></li></ul><h2 id="before-we-start" tabindex="-1">Before We Start <a class="header-anchor" href="#before-we-start" aria-label="Permalink to “Before We Start”">​</a></h2><p>Before we begin the release train, make sure that the <a href="./ROADMAP">roadmap</a> is properly updated on <code>main</code> and <code>beta</code> so that it will be accurate when the new release branch is created. To do this you likely need to reach out to WarpDrive core team members to ensure all recent planning discussions and work is properly accounted for.</p><h2 id="getting-setup-to-do-a-release" tabindex="-1">Getting Setup To Do A Release <a class="header-anchor" href="#getting-setup-to-do-a-release" aria-label="Permalink to “Getting Setup To Do A Release”">​</a></h2><p>In order to release WarpDrive you must have commit rights to <code>warp-drive-data/warp-drive</code> on GitHub, along with permission to trigger the <code>0. Release</code> workflow. Everything else is handled by automation.</p><p>Publishing to npm requires npm&#39;s <a href="https://docs.npmjs.com/trusted-publishers/" target="_blank" rel="noreferrer">Trusted Publishing</a> (OIDC), which is only available from within that GitHub Actions workflow -- there is no manual or local publish path, and no npm account, access token, or 2FA setup is needed to perform a release. For more information run <code>bun release about</code> in the repository.</p><p>If you want to run a release step locally for review (e.g. a <code>--dry-run</code>, or generating a release strategy) rather than actually publishing, you will additionally need:</p><ul><li><code>bun</code>, <code>pnpm</code> and <code>node</code> installed globally (or better, via <code>mise</code>)</li><li>A <code>GITHUB_AUTH</code> token configured for <code>lerna-changelog</code>, to gather info for the release notes</li></ul><h2 id="release-order" tabindex="-1">Release Order <a class="header-anchor" href="#release-order" aria-label="Permalink to “Release Order”">​</a></h2><p>When releasing more than one channel, we release from &quot;most stable&quot; to &quot;least stable&quot;. This is what allows changes to flow down from canary to lts versioned seamlessly.</p><ul><li><code>lts</code> (<em>Most Stable</em>)</li><li><code>release</code></li><li><code>beta</code></li><li><code>canary</code> (<em>Least Stable</em>)</li></ul><p>Since non-standard releases are always bespoke, they do not participate in the above flow.</p><p>You will find the automated workflows to perform these releases under the actions tab on github.</p><h2 id="polish-the-release" tabindex="-1">Polish the Release! <a class="header-anchor" href="#polish-the-release" aria-label="Permalink to “Polish the Release!”">​</a></h2><p>First, update the Release Notes on Github</p><ul><li>Visit <a href="https://github.com/warp-drive-data/warp-drive/releases" target="_blank" rel="noreferrer">WarpDrive Releases</a><ul><li>Click on the &quot;more recent tags&quot;</li><li>Click on the tag just published</li><li>Edit the tag, adding a meaningful title and attaching the changelog (see other releases for examples)</li><li>Publish the release!</li><li>Only set the release as latest if it should be the <code>latest</code> tag on npm as well (e.g. the <code>release</code> channel). LTS/Beta/Canary/LTS-prev/Release-prev should never be marked as <code>latest</code>.</li></ul></li></ul><p>Once you have finished this release process, we recommend posting an announcement to your Threads/Mastadon/Twitter accounts and them crosslinking the announcement to the following Discord channels:</p><h3 id="warpdrive" tabindex="-1">WarpDrive <a class="header-anchor" href="#warpdrive" aria-label="Permalink to “WarpDrive”">​</a></h3><ul><li><a href="https://discord.com/channels/999914805215367219/1400670702348271708" target="_blank" rel="noreferrer">#subspace-transmissions</a></li></ul><h3 id="emberjs" tabindex="-1">EmberJS <a class="header-anchor" href="#emberjs" aria-label="Permalink to “EmberJS”">​</a></h3><ul><li><a href="https://discordapp.com/channels/480462759797063690/480499624663056390" target="_blank" rel="noreferrer">#news-and-announcements</a></li><li><a href="https://discordapp.com/channels/480462759797063690/480501977931972608" target="_blank" rel="noreferrer">#dev-ember-data</a></li><li><a href="https://discordapp.com/channels/480462759797063690/486549196837486592" target="_blank" rel="noreferrer">#ember-data</a></li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};